// Extraer datos del mensaje de WhatsApp
// Compatible con la API de Meta WhatsApp Business
const body = $input.first().json;

let telefono = '';
let nombre = 'Cliente';
let mensaje = '';
let tipo = 'texto';

try {
  // Meta WhatsApp Cloud API format
  const entry = body.entry?.[0];
  const change = entry?.changes?.[0];
  const value = change?.value;

  if (value?.messages?.[0]) {
    const msg = value.messages[0];
    telefono = msg.from || '';
    mensaje  = msg.text?.body || msg.interactive?.button_reply?.title || '[mensaje no texto]';
    tipo     = msg.type || 'text';

    // Get name from contacts
    const contact = value.contacts?.[0];
    nombre = contact?.profile?.name || 'Cliente';
  }
} catch(e) {
  // Fallback for different webhook formats
  telefono = body.from || body.phone || body.telefono || '';
  mensaje  = body.body || body.text || body.message || '';
  nombre   = body.name || body.nombre || 'Cliente';
}

// Classify message intent
const msg_lower = mensaje.toLowerCase();
let intencion = 'general';

if (msg_lower.match(/precio|costo|cuanto|cuánto|tarifa|vale/)) intencion = 'precio';
else if (msg_lower.match(/hola|buenas|buenos|hi|hello|saludo/)) intencion = 'saludo';
else if (msg_lower.match(/horario|hora|abierto|cuando|cuándo|atienden/)) intencion = 'horario';
else if (msg_lower.match(/ubicacion|dirección|donde|dónde|mapa|llegar/)) intencion = 'ubicacion';
else if (msg_lower.match(/ayuda|ayudar|información|info|quiero|necesito/)) intencion = 'informacion';
else if (msg_lower.match(/gracias|thanks|perfecto|listo|ok|entendido/)) intencion = 'despedida';

return [{ json: {
  telefono,
  nombre,
  mensaje,
  tipo,
  intencion,
  fecha: new Date().toISOString(),
  timestamp: Date.now()
} }];
